import numpy as np, math
class Body:
 def __init__(self,x,z,w,h,m=1,static=False):
  self.p=np.array([x,z],float);self.size=np.array([w,h]);self.m=m;self.inv=0 if static else 1/m;self.I=0 if static else 12/(m*(w*w+h*h));self.a=0.;self.v=np.zeros(2);self.av=0.
 def verts(self):
  c,s=np.cos(self.a),np.sin(self.a);R=np.array([[c,-s],[s,c]])
  return np.array([[-1,-1],[1,-1],[1,1],[-1,1]])*self.size/2@R.T+self.p
 def vel(self,r):return self.v+self.av*np.array([-r[1],r[0]])
 def impulse(self,j,r):
  self.v+=j*self.inv;self.av+=np.cross(r,j)*self.I

def clip(subject,poly):
 for j in range(len(poly)):
  a=poly[j];b=poly[(j+1)%len(poly)];edge=b-a
  def side(p):return np.cross(edge,p-a)
  inp=subject;subject=[]
  if len(inp)==0:break
  prev=inp[-1];sp=side(prev)
  for cur in inp:
   sc=side(cur)
   if (sc>=0)"'!=(sp>=0):subject.append(prev+(cur-prev)*(sp/(sp-sc)))
   if sc>=0:subject.append(cur)
   prev=cur;sp=sc
 return np.array(subject)

def collide(A,B):
 va,vb=A.verts(),B.verts();small=1e9;n=None
 for V in (va,vb):
  for k in range(2):
   edge=V[k+1]-V[k];axis=np.array([-edge[1],edge[0]]);axis/=np.linalg.norm(axis)
   aa=va@axis;bb=vb@axis;over=min(aa.max(),bb.max())-max(aa.min(),bb.min())
   if over<-.001:return None
   if over<small:small=over;n=axis
 if (B.p-A.p)@n<0:n=-n
 pol=clip(list(va),vb)
 if len(pol)==0:return None
 tangent=np.array([-n[1],n[0]]);proj=pol@tangent
 cs=[pol[np.argmin(proj)],pol[np.argmax(proj)]]
 if np.linalg.norm(cs[0]-cs[1])<.1:cs=cs[:1]
 return n,small,cs

def solve(A,B,n,pen,points,dt):
 for p in points:
  ra=p-A.p;rb=p-B.p;dv=B.vel(rb)-A.vel(ra);vn=dv@n
  denom=A.inv+B.inv+A.I*np.cross(ra,n)**2+B.I*np.cross(rb,n)**2
  if denom==0:continue
  bias=.20*max(pen-.025,0)/dt
  j=max(0,(-vn+bias)/denom)
  A.impulse(-j*n,ra);B.impulse(j*n,rb)
  dv=B.vel(rb)-A.vel(ra);t=np.array([-n[1],n[0]])
  den=A.inv+B.inv+A.I*np.cross(ra,t)**2+B.I*np.cross(rb,t)**2
  jt=np.clip(-(dv@t)/den,-j*.52,j*.52)
  A.impulse(-jt*t,ra);B.impulse(jt*t,rb)

def simulate():
 yellow=Body(19.5,40,39,8,1);blue=Body(36.75,68.25,7.5,48.5,1.08);red=Body(15,18,14,36,static=True);floor=Body(100,-10,800,20,static=True)
 bodies=[yellow,blue,red,floor];states=[];dt=1/240
 for it in range(4*240+1):
  if it%60==0:states.append([(q.p.copy(),q.a) for q in bodies[:2]])
  for q in bodies[:2]:q.v[1]-=240*dt;q.v*=.9998;q.av*=.9995;q.p+=q.v*dt;q.a+=q.av*dt
  cols=[]
  for ai,bi in [(0,1),(0,2),(1,2),(0,3),(1,3)]:
   A,B=bodies[ai],bodies[bi];col=collide(A,B)
   if col:cols.append((A,B,*col))
  for _ in range(12):
   for A,B,n,pen,cs in cols:solve(A,B,n,pen,cs,dt)
 return states
if __name__=='"'__main__':
 for i,st in enumerate(simulate()):print(i/4,[(np.round(p,1).tolist(),round(a*180/np.pi,1)) for p,a in st])
